import { Composition } from "remotion";
import { ExplainerVideo } from "./ExplainerVideo";

export const RemotionRoot: React.FC = () => {
  return (
    <>
      <Composition
        id="ExplainerVideo"
        component={ExplainerVideo}
        durationInFrames={450}
        fps={30}
        width={1920}
        height={1080}
      />
    </>
  );
};

import { registerRoot } from "remotion";
import { RemotionRoot } from "./Root";

registerRoot(RemotionRoot);

import React from "react";
import { AbsoluteFill, Sequence } from "remotion";
import { TitleScene } from "./scenes/TitleScene";
import { ProblemScene } from "./scenes/ProblemScene";
import { SolutionScene } from "./scenes/SolutionScene";
import { HowItWorksScene } from "./scenes/HowItWorksScene";
import { ProofGateScene } from "./scenes/ProofGateScene";
import { ClosingScene } from "./scenes/ClosingScene";

export const ExplainerVideo: React.FC = () => {
  return (
    <AbsoluteFill style={{ backgroundColor: "#0f0f1a" }}>
      {/* Scene 1: Title - 0 to 75 (2.5s) */}
      <Sequence from={0} durationInFrames={75}>
        <TitleScene />
      </Sequence>

      {/* Scene 2: The Problem - 75 to 165 (3s) */}
      <Sequence from={75} durationInFrames={90}>
        <ProblemScene />
      </Sequence>

      {/* Scene 3: The Solution - 165 to 255 (3s) */}
      <Sequence from={165} durationInFrames={90}>
        <SolutionScene />
      </Sequence>

      {/* Scene 4: How It Works - 255 to 345 (3s) */}
      <Sequence from={255} durationInFrames={90}>
        <HowItWorksScene />
      </Sequence>

      {/* Scene 5: ProofGate - 345 to 405 (2s) */}
      <Sequence from={345} durationInFrames={60}>
        <ProofGateScene />
      </Sequence>

      {/* Scene 6: Closing - 405 to 450 (1.5s) */}
      <Sequence from={405} durationInFrames={45}>
        <ClosingScene />
      </Sequence>
    </AbsoluteFill>
  );
};

import React from "react";
import {
  AbsoluteFill,
  interpolate,
  useCurrentFrame,
  spring,
  useVideoConfig,
} from "remotion";

export const TitleScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const titleScale = spring({ frame, fps, config: { damping: 12 } });
  const subtitleOpacity = interpolate(frame, [20, 40], [0, 1], {
    extrapolateRight: "clamp",
  });
  const lineWidth = interpolate(frame, [15, 45], [0, 400], {
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        justifyContent: "center",
        alignItems: "center",
        background: "linear-gradient(135deg, #0f0f1a 0%, #1a1a3e 100%)",
      }}
    >
      {/* Decorative circles */}
      <div
        style={{
          position: "absolute",
          width: 300,
          height: 300,
          borderRadius: "50%",
          border: "2px solid rgba(99, 102, 241, 0.2)",
          top: 100,
          right: 200,
          transform: `scale(${interpolate(frame, [0, 60], [0.5, 1.2], { extrapolateRight: "clamp" })})`,
          opacity: 0.3,
        }}
      />
      <div
        style={{
          position: "absolute",
          width: 200,
          height: 200,
          borderRadius: "50%",
          border: "2px solid rgba(16, 185, 129, 0.2)",
          bottom: 150,
          left: 250,
          transform: `scale(${interpolate(frame, [10, 70], [0.5, 1.3], { extrapolateRight: "clamp" })})`,
          opacity: 0.3,
        }}
      />

      <div style={{ textAlign: "center", transform: `scale(${titleScale})` }}>
        <div
          style={{
            fontSize: 28,
            color: "#6366f1",
            fontFamily: "system-ui, sans-serif",
            fontWeight: 600,
            letterSpacing: 6,
            textTransform: "uppercase",
            marginBottom: 20,
          }}
        >
          Introducing
        </div>
        <div
          style={{
            fontSize: 90,
            fontWeight: 800,
            fontFamily: "system-ui, sans-serif",
            background: "linear-gradient(90deg, #6366f1, #10b981)",
            WebkitBackgroundClip: "text",
            WebkitTextFillColor: "transparent",
            lineHeight: 1.1,
          }}
        >
          External Agents
        </div>
        <div
          style={{
            width: lineWidth,
            height: 3,
            background: "linear-gradient(90deg, #6366f1, #10b981)",
            margin: "20px auto",
            borderRadius: 2,
          }}
        />
        <div
          style={{
            fontSize: 32,
            color: "#94a3b8",
            fontFamily: "system-ui, sans-serif",
            fontWeight: 400,
            opacity: subtitleOpacity,
          }}
        >
          Trust & Governance for AI Coding Agents
        </div>
      </div>
    </AbsoluteFill>
  );
};

import React from "react";
import {
  AbsoluteFill,
  interpolate,
  useCurrentFrame,
  spring,
  useVideoConfig,
} from "remotion";

const WarningIcon: React.FC<{ delay: number }> = ({ delay }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const appear = spring({ frame: Math.max(0, frame - delay), fps, config: { damping: 10 } });

  return (
    <div
      style={{
        transform: `scale(${appear})`,
        fontSize: 48,
        marginBottom: 8,
      }}
    >
      <svg width="48" height="48" viewBox="0 0 24 24" fill="none">
        <path
          d="M12 9v4m0 4h.01M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"
          stroke="#f59e0b"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
    </div>
  );
};

export const ProblemScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const headerSlide = spring({ frame, fps, config: { damping: 12 } });

  const problems = [
    "No audit trail of AI changes",
    "Self-reported test results",
    "No checkpoint / rewind ability",
  ];

  return (
    <AbsoluteFill
      style={{
        justifyContent: "center",
        alignItems: "center",
        background: "linear-gradient(135deg, #1a0f0f 0%, #2d1b1b 100%)",
      }}
    >
      <div style={{ textAlign: "center", maxWidth: 1200 }}>
        <div
          style={{
            fontSize: 56,
            fontWeight: 700,
            fontFamily: "system-ui, sans-serif",
            color: "#f87171",
            marginBottom: 60,
            transform: `translateY(${interpolate(headerSlide, [0, 1], [40, 0])}px)`,
            opacity: headerSlide,
          }}
        >
          The Problem
        </div>

        <div
          style={{
            display: "flex",
            gap: 40,
            justifyContent: "center",
          }}
        >
          {problems.map((problem, i) => {
            const delay = 15 + i * 12;
            const cardAppear = spring({
              frame: Math.max(0, frame - delay),
              fps,
              config: { damping: 12 },
            });

            return (
              <div
                key={i}
                style={{
                  background: "rgba(248, 113, 113, 0.08)",
                  border: "1px solid rgba(248, 113, 113, 0.3)",
                  borderRadius: 16,
                  padding: "40px 36px",
                  width: 300,
                  transform: `scale(${cardAppear}) translateY(${interpolate(cardAppear, [0, 1], [30, 0])}px)`,
                  opacity: cardAppear,
                }}
              >
                <WarningIcon delay={delay + 5} />
                <div
                  style={{
                    fontSize: 24,
                    fontWeight: 600,
                    fontFamily: "system-ui, sans-serif",
                    color: "#fca5a5",
                    lineHeight: 1.4,
                  }}
                >
                  {problem}
                </div>
              </div>
            );
          })}
        </div>

        <div
          style={{
            marginTop: 50,
            fontSize: 28,
            color: "#94a3b8",
            fontFamily: "system-ui, sans-serif",
            opacity: interpolate(frame, [50, 70], [0, 1], {
              extrapolateRight: "clamp",
            }),
          }}
        >
          AI agents write code... but who watches the watchers?
        </div>
      </div>
    </AbsoluteFill>
  );
};

import React from "react";
import {
  AbsoluteFill,
  interpolate,
  useCurrentFrame,
  spring,
  useVideoConfig,
} from "remotion";

const AgentBadge: React.FC<{ name: string; delay: number; color: string }> = ({
  name,
  delay,
  color,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const appear = spring({
    frame: Math.max(0, frame - delay),
    fps,
    config: { damping: 10 },
  });

  return (
    <div
      style={{
        background: `${color}15`,
        border: `1px solid ${color}50`,
        borderRadius: 12,
        padding: "12px 24px",
        transform: `scale(${appear})`,
        opacity: appear,
      }}
    >
      <span
        style={{
          fontSize: 20,
          fontWeight: 600,
          fontFamily: "system-ui, sans-serif",
          color,
        }}
      >
        {name}
      </span>
    </div>
  );
};

export const SolutionScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const headerAppear = spring({ frame, fps, config: { damping: 12 } });
  const descOpacity = interpolate(frame, [15, 35], [0, 1], {
    extrapolateRight: "clamp",
  });

  const agents = [
    { name: "Claude Code", color: "#c084fc", delay: 25 },
    { name: "Kiro", color: "#60a5fa", delay: 30 },
    { name: "Grok", color: "#f472b6", delay: 35 },
    { name: "Qwen", color: "#34d399", delay: 40 },
    { name: "Goose", color: "#fbbf24", delay: 45 },
    { name: "GitHub Actions", color: "#fb923c", delay: 50 },
  ];

  return (
    <AbsoluteFill
      style={{
        justifyContent: "center",
        alignItems: "center",
        background: "linear-gradient(135deg, #0f1a0f 0%, #1b2d1b 100%)",
      }}
    >
      <div style={{ textAlign: "center", maxWidth: 1200 }}>
        <div
          style={{
            fontSize: 56,
            fontWeight: 700,
            fontFamily: "system-ui, sans-serif",
            color: "#10b981",
            marginBottom: 20,
            transform: `translateY(${interpolate(headerAppear, [0, 1], [40, 0])}px)`,
            opacity: headerAppear,
          }}
        >
          The Solution
        </div>

        <div
          style={{
            fontSize: 30,
            color: "#d1d5db",
            fontFamily: "system-ui, sans-serif",
            marginBottom: 50,
            opacity: descOpacity,
            lineHeight: 1.5,
          }}
        >
          Plug <strong style={{ color: "#a5b4fc" }}>any AI agent</strong> into a
          unified governance system
        </div>

        {/* Agent grid */}
        <div
          style={{
            display: "flex",
            flexWrap: "wrap",
            gap: 16,
            justifyContent: "center",
            marginBottom: 50,
          }}
        >
          {agents.map((agent) => (
            <AgentBadge key={agent.name} {...agent} />
          ))}
        </div>

        {/* Arrow down */}
        <div
          style={{
            opacity: interpolate(frame, [55, 65], [0, 1], {
              extrapolateRight: "clamp",
            }),
          }}
        >
          <svg width="60" height="60" viewBox="0 0 24 24" fill="none">
            <path
              d="M12 5v14m0 0l-7-7m7 7l7-7"
              stroke="#10b981"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </div>

        <div
          style={{
            fontSize: 26,
            fontWeight: 700,
            fontFamily: "system-ui, sans-serif",
            color: "#6366f1",
            marginTop: 16,
            opacity: interpolate(frame, [60, 75], [0, 1], {
              extrapolateRight: "clamp",
            }),
            background: "rgba(99, 102, 241, 0.1)",
            border: "1px solid rgba(99, 102, 241, 0.3)",
            borderRadius: 12,
            padding: "14px 40px",
            display: "inline-block",
          }}
        >
          Entire CLI + External Agents Protocol
        </div>
      </div>
    </AbsoluteFill>
  );
};

import React from "react";
import {
  AbsoluteFill,
  interpolate,
  useCurrentFrame,
  spring,
  useVideoConfig,
} from "remotion";

interface StepProps {
  number: string;
  title: string;
  desc: string;
  delay: number;
  color: string;
}

const FlowStep: React.FC<StepProps> = ({
  number,
  title,
  desc,
  delay,
  color,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const appear = spring({
    frame: Math.max(0, frame - delay),
    fps,
    config: { damping: 12 },
  });

  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: 20,
        transform: `translateX(${interpolate(appear, [0, 1], [-60, 0])}px)`,
        opacity: appear,
      }}
    >
      <div
        style={{
          width: 56,
          height: 56,
          borderRadius: "50%",
          background: `${color}20`,
          border: `2px solid ${color}`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontSize: 24,
          fontWeight: 800,
          fontFamily: "system-ui, sans-serif",
          color,
          flexShrink: 0,
        }}
      >
        {number}
      </div>
      <div>
        <div
          style={{
            fontSize: 26,
            fontWeight: 700,
            fontFamily: "system-ui, sans-serif",
            color: "#e2e8f0",
          }}
        >
          {title}
        </div>
        <div
          style={{
            fontSize: 20,
            color: "#94a3b8",
            fontFamily: "system-ui, sans-serif",
          }}
        >
          {desc}
        </div>
      </div>
    </div>
  );
};

export const HowItWorksScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const headerAppear = spring({ frame, fps, config: { damping: 12 } });

  const steps: Omit<StepProps, "delay">[] = [
    {
      number: "1",
      title: "Agent Hooks In",
      desc: "External agent binary intercepts lifecycle events",
      color: "#c084fc",
    },
    {
      number: "2",
      title: "Capture Evidence",
      desc: "Transcripts, checkpoints, file changes recorded",
      color: "#60a5fa",
    },
    {
      number: "3",
      title: "Build Change Passport",
      desc: "Structured evidence package with full provenance",
      color: "#10b981",
    },
    {
      number: "4",
      title: "ProofGate Evaluates",
      desc: "Deterministic policy engine scores the change",
      color: "#f59e0b",
    },
    {
      number: "5",
      title: "Decision Rendered",
      desc: "PASS, WARN, or APPROVAL_REQUIRED",
      color: "#f87171",
    },
  ];

  // Animated connector line
  const lineHeight = interpolate(frame, [10, 70], [0, 380], {
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        justifyContent: "center",
        alignItems: "center",
        background: "linear-gradient(135deg, #0f0f1a 0%, #1a1a3e 100%)",
      }}
    >
      <div style={{ display: "flex", gap: 100, alignItems: "flex-start" }}>
        {/* Left: Title */}
        <div
          style={{
            transform: `translateY(${interpolate(headerAppear, [0, 1], [40, 0])}px)`,
            opacity: headerAppear,
          }}
        >
          <div
            style={{
              fontSize: 52,
              fontWeight: 700,
              fontFamily: "system-ui, sans-serif",
              background: "linear-gradient(180deg, #6366f1, #10b981)",
              WebkitBackgroundClip: "text",
              WebkitTextFillColor: "transparent",
              lineHeight: 1.2,
              width: 300,
            }}
          >
            How It Works
          </div>
        </div>

        {/* Right: Steps */}
        <div style={{ position: "relative" }}>
          {/* Vertical connector line */}
          <div
            style={{
              position: "absolute",
              left: 27,
              top: 56,
              width: 2,
              height: lineHeight,
              background:
                "linear-gradient(180deg, #c084fc, #60a5fa, #10b981, #f59e0b, #f87171)",
              opacity: 0.4,
            }}
          />

          <div style={{ display: "flex", flexDirection: "column", gap: 28 }}>
            {steps.map((step, i) => (
              <FlowStep key={i} {...step} delay={8 + i * 10} />
            ))}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

import React from "react";
import {
  AbsoluteFill,
  interpolate,
  useCurrentFrame,
  spring,
  useVideoConfig,
} from "remotion";

export const ProofGateScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const shieldScale = spring({ frame, fps, config: { damping: 8 } });
  const textOpacity = interpolate(frame, [15, 30], [0, 1], {
    extrapolateRight: "clamp",
  });

  const features = [
    "Immutable evidence - no LLM can change the verdict",
    "Deterministic policy - same facts = same decision",
    "Privacy-first - sensitive data stays local",
  ];

  // Pulsing glow
  const glowOpacity = interpolate(
    Math.sin(frame * 0.1),
    [-1, 1],
    [0.1, 0.4]
  );

  return (
    <AbsoluteFill
      style={{
        justifyContent: "center",
        alignItems: "center",
        background: "linear-gradient(135deg, #0f1a1a 0%, #1a2d3e 100%)",
      }}
    >
      <div style={{ display: "flex", alignItems: "center", gap: 80 }}>
        {/* Shield icon */}
        <div
          style={{
            transform: `scale(${shieldScale})`,
            position: "relative",
          }}
        >
          <div
            style={{
              position: "absolute",
              inset: -20,
              borderRadius: "50%",
              background: "radial-gradient(circle, rgba(16, 185, 129, 0.3), transparent)",
              opacity: glowOpacity,
            }}
          />
          <svg width="160" height="160" viewBox="0 0 24 24" fill="none">
            <path
              d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"
              stroke="#10b981"
              strokeWidth="1.5"
              fill="rgba(16, 185, 129, 0.1)"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
            <path
              d="M9 12l2 2 4-4"
              stroke="#10b981"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </div>

        {/* Text */}
        <div style={{ opacity: textOpacity }}>
          <div
            style={{
              fontSize: 52,
              fontWeight: 800,
              fontFamily: "system-ui, sans-serif",
              color: "#10b981",
              marginBottom: 30,
            }}
          >
            ProofGate
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 18 }}>
            {features.map((feat, i) => {
              const featOpacity = interpolate(
                frame,
                [20 + i * 8, 30 + i * 8],
                [0, 1],
                { extrapolateRight: "clamp" }
              );
              return (
                <div
                  key={i}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 14,
                    opacity: featOpacity,
                  }}
                >
                  <div
                    style={{
                      width: 8,
                      height: 8,
                      borderRadius: "50%",
                      background: "#10b981",
                      flexShrink: 0,
                    }}
                  />
                  <span
                    style={{
                      fontSize: 24,
                      color: "#d1d5db",
                      fontFamily: "system-ui, sans-serif",
                    }}
                  >
                    {feat}
                  </span>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

import React from "react";
import {
  AbsoluteFill,
  interpolate,
  useCurrentFrame,
  spring,
  useVideoConfig,
} from "remotion";

export const ClosingScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const titleScale = spring({ frame, fps, config: { damping: 10 } });
  const subtitleOpacity = interpolate(frame, [10, 25], [0, 1], {
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        justifyContent: "center",
        alignItems: "center",
        background: "linear-gradient(135deg, #0f0f1a 0%, #1a1a3e 100%)",
      }}
    >
      {/* Decorative gradient orbs */}
      <div
        style={{
          position: "absolute",
          width: 400,
          height: 400,
          borderRadius: "50%",
          background:
            "radial-gradient(circle, rgba(99, 102, 241, 0.15), transparent)",
          top: -100,
          right: -50,
        }}
      />
      <div
        style={{
          position: "absolute",
          width: 350,
          height: 350,
          borderRadius: "50%",
          background:
            "radial-gradient(circle, rgba(16, 185, 129, 0.15), transparent)",
          bottom: -80,
          left: -50,
        }}
      />

      <div
        style={{ textAlign: "center", transform: `scale(${titleScale})` }}
      >
        <div
          style={{
            fontSize: 64,
            fontWeight: 800,
            fontFamily: "system-ui, sans-serif",
            background: "linear-gradient(90deg, #6366f1, #10b981)",
            WebkitBackgroundClip: "text",
            WebkitTextFillColor: "transparent",
            marginBottom: 24,
          }}
        >
          Ship AI Code with Confidence
        </div>
        <div
          style={{
            fontSize: 28,
            color: "#94a3b8",
            fontFamily: "system-ui, sans-serif",
            opacity: subtitleOpacity,
          }}
        >
          External Agents + ProofGate
        </div>
        <div
          style={{
            marginTop: 30,
            fontSize: 22,
            color: "#64748b",
            fontFamily: "monospace",
            opacity: subtitleOpacity,
          }}
        >
          github.com/entireio/external-agents
        </div>
      </div>
    </AbsoluteFill>
  );
};
